def item(domain: str, band: str, grade: str, topic: str, difficulty: str,
         problem: str, turns: list[tuple[str, str]], solution: str,
         misconception: str, response: str, next_step: str) -> dict[str, Any]:
    return {
        "domain": domain, "band": band, "grade": grade, "topic": topic,
        "difficulty": difficulty, "problem": problem, "turns": turns,
        "solution": solution, "misconception": misconception,
        "response": response, "next_step": next_step,
    }


