def extra(domain: str, band: str, grade: str, topic: str, difficulty: str,
          problem: str, student: str, solution: str, misconception: str,
          response: str, next_step: str) -> dict[str, Any]:
    """Compact authoring helper for additional context-specific cases."""
    starters = [
        "Let's examine the quantities in this problem before choosing an operation.",
        "Show me how you interpreted the question and the step you tried.",
        "Let's test your idea against the relationship described in the problem.",
        "Pause at the step where the quantities or shapes connect. What do you notice?",
        "Let's use the meaning of the math, not just a remembered rule, to check this.",
        "Can we represent the situation another way and compare it with your result?",
    ]
    starter = starters[len(CASES) % len(starters)]
    return item(
        domain, band, grade, topic, difficulty, problem,
        [("Tutor", f"{starter} {problem}"), ("Student", student)],
        solution, misconception, response, next_step,
    )


