def revise_case(domain: str, ordinal: int, *, topic: str, problem: str, student: str,
                solution: str, misconception: str, response: str, next_step: str) -> None:
    """Replace an over-similar seed while preserving its domain and grade-band slot."""
    domain_cases = [i for i, case in enumerate(CASES) if case["domain"] == domain]
    index = domain_cases[ordinal - 1]
    old = CASES[index]
    CASES[index] = item(
        domain, old["band"], old["grade"], topic, old["difficulty"], problem,
        [("Tutor", f"Let's reason through this situation. {problem}"), ("Student", student)],
        solution, misconception, response, next_step,
    )


