CONTEXT_FIELDS = [
    "context_id", "primary_domain", "subtopic", "secondary_topics", "grade_band", "grade_level", "difficulty", "language",
    "problem_text", "turns_json", "conversation_history", "student_last_utterance", "ground_truth_solution", "misconception_type",
    "source_name", "source_url", "source_license", "source_version", "collection_method", "is_original", "created_by",
    "math_verified_by", "context_review_status", "problem_family_id", "split_group",
]
LABEL_FIELDS = [
    "Mistake_Identification", "Mistake_Location", "Revealing_of_the_Answer", "Providing_Guidance",
    "Actionability", "Coherence", "Tutor_Tone", "Humanlikeness",
]
RESPONSE_FIELDS = [
    "response_id", "context_id", "tutor_name", "tutor_type", "response_raw", "model_revision", "prompt_version",
    "generation_parameters", *LABEL_FIELDS, "annotator_1", "annotator_2", "adjudicator_id", "annotation_method",
    "guideline_version", "review_status", "evidence_notes", "draft_diagnosis", "draft_next_step", "draft_style",
]


def normalize(text: str, replace_numbers: bool = False) -> str:
    text = str(text or "").lower().replace("\ufffd", " ")
    if replace_numbers:
        text = re.sub(r"(?<![a-z])[-+]?\d+(?:[,.]\d+)*(?:/\d+)?", " <number> ", text)
    text = re.sub(r"[^a-z0-9<>]+", " ", text)
    return " ".join(text.split())


def sim_matrix(left: list[str], right: list[str], *, normalize_numbers: bool = False) -> np.ndarray:
    left_clean = [normalize(x, normalize_numbers) for x in left]
    right_clean = [normalize(x, normalize_numbers) for x in right]
    vec = TfidfVectorizer(analyzer="char_wb", ngram_range=(3, 5), min_df=1, sublinear_tf=True)
    matrix = vec.fit_transform(left_clean + right_clean)
    return cosine_similarity(matrix[:len(left_clean)], matrix[len(left_clean):])


def read_csv(path: Path) -> list[dict[str, str]]:
    with path.open("r", encoding="utf-8-sig", newline="") as f:
        return list(csv.DictReader(f))


def write_csv(path: Path, rows: list[dict[str, Any]], fieldnames: list[str]) -> None:
    with path.open("w", encoding="utf-8-sig", newline="") as f:
        writer = csv.DictWriter(f, fieldnames=fieldnames, extrasaction="ignore")
        writer.writeheader()
        writer.writerows(rows)


def make_rows() -> tuple[list[dict[str, Any]], list[dict[str, Any]]]:
    contexts: list[dict[str, Any]] = []
    responses: list[dict[str, Any]] = []
    per_domain: Counter[str] = Counter()
    for case in CASES:
        domain = case["domain"]
        per_domain[domain] += 1
        context_id = f"{domain}-B01-{per_domain[domain]:03d}"
        history = "\n".join(f"{role}: {text}" for role, text in case["turns"])
        last_student = next(text for role, text in reversed(case["turns"]) if role == "Student")
        topic_slug = re.sub(r"[^a-z0-9]+", "-", case["topic"].lower()).strip("-")
        contexts.append({
            "context_id": context_id,
            "primary_domain": domain,
            "subtopic": case["topic"],
            "secondary_topics": "",
            "grade_band": case["band"],
            "grade_level": case["grade"],
            "difficulty": case["difficulty"],
            "language": "en",
            "problem_text": case["problem"],
            "turns_json": json.dumps([{"role": r, "text": t} for r, t in case["turns"]], ensure_ascii=False),
            "conversation_history": history,
            "student_last_utterance": last_student,
            "ground_truth_solution": case["solution"],
            "misconception_type": case["misconception"],
            "source_name": "TeamD1D4OriginalDraft",
            "source_url": "",
            "source_license": "team-license-to-be-decided",
            "source_version": VERSION,
            "collection_method": "AI-assisted original drafting; AI quality review complete; human review pending",
            "is_original": True,
            "created_by": "AI-assisted candidate; team member must review/rewrite before claiming authorship",
            "math_verified_by": "AI consistency review only; human verification pending",
            "context_review_status": "ai_reviewed; pending_human_review",
            "problem_family_id": f"{domain}-{topic_slug}",
            "split_group": context_id,
        })
        responses.append({
            "response_id": f"{context_id}::HumanTutorDraft",
            "context_id": context_id,
            "tutor_name": "TeamHumanTutorDraft",
            "tutor_type": "AI-assisted human-tutor-style draft; not yet human-authored/approved",
            "response_raw": case["response"],
            "model_revision": "",
            "prompt_version": "",
            "generation_parameters": "",
            **{field: "" for field in LABEL_FIELDS},
            "annotator_1": "",
            "annotator_2": "",
            "adjudicator_id": "",
            "annotation_method": "not_annotated",
            "guideline_version": "",
            "review_status": "ai_reviewed; human_author_review_pending; not_gold",
            "evidence_notes": "AI draft checked for mathematical and pedagogical fit; a team member must independently verify and adopt or rewrite it before treating it as a human tutor response.",
            "draft_diagnosis": case["misconception"],
            "draft_next_step": case["next_step"],
            "draft_style": "context_specific_guided_feedback",
        })
    return contexts, responses


def source_data() -> tuple[list[dict[str, Any]], list[dict[str, Any]]]:
    """Load every MRBench V1 dialogue and tutor response used by the source paper."""
    original = json.loads(SOURCE_PATH.read_text(encoding="utf-8-sig"))
    mr_contexts: list[dict[str, Any]] = []
    mr_responses: list[dict[str, Any]] = []
    for i, obj in enumerate(original):
        conversation_id = str(obj.get("conversation_id", i))
        history = str(obj.get("conversation_history", ""))
        mr_contexts.append({"id": f"MRBench::{conversation_id}", "text": history})
        for tutor, value in (obj.get("anno_llm_responses") or {}).items():
            response = value.get("response", "") if isinstance(value, dict) else str(value)
            if str(response).strip():
                mr_responses.append({
                    "id": f"{conversation_id}::{tutor}",
                    "context_id": f"MRBench::{conversation_id}",
                    "text": str(response),
                })
    return mr_contexts, mr_responses


def audit(contexts: list[dict[str, Any]], responses: list[dict[str, Any]]) -> tuple[list[dict[str, Any]], list[dict[str, Any]], dict[str, Any]]:
    mr_contexts, mr_responses = source_data()
    candidate_contexts = [f"{r['problem_text']}\n{r['student_last_utterance']}" for r in contexts]
    source_contexts = [r["text"] for r in mr_contexts]
    raw_ctx = sim_matrix(candidate_contexts, source_contexts)
    norm_ctx = sim_matrix(candidate_contexts, source_contexts, normalize_numbers=True)
    internal_ctx = sim_matrix(candidate_contexts, candidate_contexts, normalize_numbers=True)
    np.fill_diagonal(internal_ctx, -1.0)
    source_context_norm = [normalize(x) for x in source_contexts]
    source_response_norm = {normalize(x["text"]) for x in mr_responses}
    reviewed_source_flags = {
        "D3-B01-005": "MRBench neighbor is a quadrilateral-classification dialogue; this item asks for the fourth interior angle.",
        "D2-B01-034": "MRBench neighbor asks for a missing divisor; this item asks for a missing addend in an addition equation.",
        "D3-B01-014": "MRBench neighbor measures a line segment; this item computes a rectangle's perimeter from four sides.",
        "D3-B01-024": "MRBench neighbor measures a line segment; this item uses the circle circumference formula.",
        "D3-B01-040": "MRBench neighbor measures a line segment; this item computes triangle area from base and perpendicular height.",
        "D2-B01-046": "MRBench neighbor is an elementary division dialogue; this item compares products of two transformation matrices. Similarity is lexical, not a shared task.",
        "D3-B01-045": "MRBench neighbor measures a crayon segment; this item derives rhombus area from diagonals. Similarity comes from generic measurement words.",
    }
    context_audit: list[dict[str, Any]] = []
    for i, context in enumerate(contexts):
        j_raw, j_norm = int(raw_ctx[i].argmax()), int(norm_ctx[i].argmax())
        j_internal = int(internal_ctx[i].argmax())
        problem_norm = normalize(context["problem_text"])
        student_norm = normalize(context["student_last_utterance"])
        pair_norm = normalize(candidate_contexts[i])
        exact_problem = any(problem_norm and problem_norm in source for source in source_context_norm)
        exact_student = any(student_norm and student_norm in source for source in source_context_norm)
        exact_pair = pair_norm in set(source_context_norm)
        source_raw_score, source_norm_score = float(raw_ctx[i, j_raw]), float(norm_ctx[i, j_norm])
        internal_score = float(internal_ctx[i, j_internal])
        flag = exact_problem or exact_student or exact_pair or source_raw_score >= 0.35 or source_norm_score >= 0.42 or internal_score >= 0.62
        context_audit.append({
            "context_id": context["context_id"],
            "nearest_mrbench_context_id_raw": mr_contexts[j_raw]["id"],
            "mrbench_context_raw_similarity": round(source_raw_score, 4),
            "nearest_mrbench_context_id_numbers_normalized": mr_contexts[j_norm]["id"],
            "mrbench_context_numbers_normalized_similarity": round(source_norm_score, 4),
            "nearest_new_context_id_numbers_normalized": contexts[j_internal]["context_id"],
            "new_context_numbers_normalized_similarity": round(internal_score, 4),
            "exact_problem_text_in_mrbench": exact_problem,
            "exact_student_utterance_in_mrbench": exact_student,
            "exact_context_pair_in_mrbench": exact_pair,
            "flag_for_manual_duplicate_review": flag,
            "ai_review_note": reviewed_source_flags.get(context["context_id"], ""),
            "review_status": ("exact_duplicate_remove" if exact_problem or exact_student or exact_pair else
                              "AI_reviewed_distinct_task; team_human_signoff_pending" if context["context_id"] in reviewed_source_flags else
                              "no_lexical_flag; human sign-off still required"),
        })

    candidate_responses = [r["response_raw"] for r in responses]
    source_responses = [r["text"] for r in mr_responses]
    response_sim = sim_matrix(candidate_responses, source_responses)
    internal_resp = sim_matrix(candidate_responses, candidate_responses)
    np.fill_diagonal(internal_resp, -1.0)
    response_audit: list[dict[str, Any]] = []
    for i, response in enumerate(responses):
        j_source, j_internal = int(response_sim[i].argmax()), int(internal_resp[i].argmax())
        source_score, internal_score = float(response_sim[i, j_source]), float(internal_resp[i, j_internal])
        exact = normalize(response["response_raw"]) in source_response_norm
        flag = exact or source_score >= 0.55 or internal_score >= 0.85
        response_audit.append({
            "response_id": response["response_id"],
            "context_id": response["context_id"],
            "nearest_mrbench_response_id": mr_responses[j_source]["id"],
            "mrbench_response_similarity": round(source_score, 4),
            "nearest_new_response_id": responses[j_internal]["response_id"],
            "new_response_similarity": round(internal_score, 4),
            "exact_response_text_match_in_mrbench": exact,
            "flag_for_manual_duplicate_review": flag,
            "review_status": "manual_semantic_review_required" if flag else "no_lexical_flag; human sign-off still required",
        })

    context_pairs = [
        (contexts[i]["context_id"], contexts[j]["context_id"], round(float(internal_ctx[i, j]), 4))
        for i in range(len(contexts)) for j in range(i + 1, len(contexts)) if internal_ctx[i, j] >= 0.62
    ]
    response_pairs = [
        (responses[i]["response_id"], responses[j]["response_id"], round(float(internal_resp[i, j]), 4))
        for i in range(len(responses)) for j in range(i + 1, len(responses))
        if responses[i]["context_id"] != responses[j]["context_id"] and internal_resp[i, j] >= 0.85
    ]
    bands = Counter(c["grade_band"] for c in contexts)
    domains = Counter(c["primary_domain"] for c in contexts)
    exact_contexts = sum(bool(r["exact_problem_text_in_mrbench"] or r["exact_student_utterance_in_mrbench"] or r["exact_context_pair_in_mrbench"]) for r in context_audit)
    exact_responses = sum(bool(r["exact_response_text_match_in_mrbench"]) for r in response_audit)
    summary = {
        "dataset": "Full D1-D4 AI-assisted context and tutor-response draft",
        "version": VERSION,
        "contexts": len(contexts),
        "responses": len(responses),
        "contexts_by_domain": dict(sorted(domains.items())),
        "contexts_by_grade_band": dict(sorted(bands.items())),
        "source_inventory": {"mrbench_contexts": len(mr_contexts), "mrbench_tutor_responses": len(mr_responses)},
        "duplicate_screen": {
            "method": "Exact normalized text matching plus TF-IDF char_wb cosine (character n-grams 3-5, sublinear_tf=True); lexical screen only",
            "thresholds": {"context_source_raw_flag": 0.35, "context_source_numbers_normalized_flag": 0.42, "context_internal_pair": 0.62, "response_source_flag": 0.55, "response_internal_pair": 0.85},
            "exact_context_matches_in_mrbench": exact_contexts,
            "exact_response_matches_in_mrbench": exact_responses,
            "context_review_flags": sum(bool(x["flag_for_manual_duplicate_review"]) for x in context_audit),
            "response_review_flags": sum(bool(x["flag_for_manual_duplicate_review"]) for x in response_audit),
            "ai_reviewed_source_flags_without_duplicate_found": sum(
                bool(r["flag_for_manual_duplicate_review"]) and r["context_id"] in reviewed_source_flags
                for r in context_audit
            ),
            "ai_reviewed_source_flag_context_ids": [
                r["context_id"] for r in context_audit
                if r["flag_for_manual_duplicate_review"] and r["context_id"] in reviewed_source_flags
            ],
            "team_human_signoff_pending_for_source_flags": True,
            "internal_context_pairs_at_threshold": len(context_pairs),
            "internal_response_pairs_at_threshold": len(response_pairs),
            "max_mrbench_context_raw_similarity": round(float(raw_ctx.max()), 4),
            "max_mrbench_context_numbers_normalized_similarity": round(float(norm_ctx.max()), 4),
            "max_mrbench_response_similarity": round(float(response_sim.max()), 4),
            "max_internal_context_similarity": round(float(internal_ctx.max()), 4),
            "max_internal_response_similarity": round(float(internal_resp.max()), 4),
            "limitations": [
                "The lexical thresholds are project screening rules, not thresholds reported by MRBench.",
                "Exact normalized match is a reproducible textual check; TF-IDF is not proof of semantic uniqueness.",
                "All current source-neighbor flags have AI review notes, but a team member must confirm semantic distinction before release.",
            ],
        },
        "annotation_status": "Tutor responses are AI-assisted drafts, not human-authored or approved; annotation labels are blank and no gold labels exist.",
        "quality_review": {
            "new_pairs_added_this_revision": 24,
            "existing_draft_pairs_corrected_this_revision": 14,
            "all_pair_review": "All 184 context-response pairs were reviewed for a clear student error or confusion, mathematical consistency, response-to-context alignment, actionable tutoring, and topical distinction. This is an AI review, not teacher sign-off.",
            "source_neighbor_flags_ai_reviewed_as_distinct": sum(
                bool(r["flag_for_manual_duplicate_review"]) and r["context_id"] in reviewed_source_flags
                for r in context_audit
            ),
            "human_review_required": True,
        },
        "required_before_release": [
            f"Human review of all {len(contexts)} contexts for mathematical correctness, grade fit, clarity, and novelty.",
            "Human tutor authors must adopt or rewrite each response before calling it human-authored.",
            "Review all context and response lexical flags; exact matches must be resolved before release.",
            "Decide team attribution and license before public release.",
            "Generate LLM tutor responses and independent human annotations before computing the paper's human-reference metrics.",
        ],
    }
    return context_audit, response_audit, summary


def main() -> None:
    expected_bands = {"D1": {"pre_k": 4, "primary": 14, "lower_secondary": 14, "upper_secondary": 9, "tertiary": 5},
                      "D2": {"pre_k": 4, "primary": 12, "lower_secondary": 13, "upper_secondary": 11, "tertiary": 6},
                      "D3": {"pre_k": 5, "primary": 13, "lower_secondary": 15, "upper_secondary": 8, "tertiary": 5},
                      "D4": {"pre_k": 5, "primary": 13, "lower_secondary": 14, "upper_secondary": 9, "tertiary": 5}}
    if len(CASES) != 184:
        raise RuntimeError(f"Expected 184 examples, found {len(CASES)}")
    if Counter(x["domain"] for x in CASES) != Counter({"D1": 46, "D2": 46, "D3": 46, "D4": 46}):
        raise RuntimeError("Each domain must have exactly 46 contexts")
    for domain in ("D1", "D2", "D3", "D4"):
        if Counter(x["band"] for x in CASES if x["domain"] == domain) != Counter(expected_bands[domain]):
            raise RuntimeError(f"Unexpected grade-band allocation for {domain}")
    contexts, responses = make_rows()
    if len({r["context_id"] for r in contexts}) != len(contexts) or len({r["response_id"] for r in responses}) != len(responses):
        raise RuntimeError("Duplicate context/response IDs")
    response_counts = Counter(r["context_id"] for r in responses)
    if len(responses) != len(contexts) or response_counts != Counter({c["context_id"]: 1 for c in contexts}):
        raise RuntimeError("Every context must have exactly one tutor-response pair")
    if any(not c["conversation_history"].splitlines()[-1].startswith("Student:") for c in contexts):
        raise RuntimeError("Every dialogue must end with a student turn")
    if any(not c["problem_text"].strip() or not c["ground_truth_solution"].strip() or not c["misconception_type"].strip() for c in contexts):
        raise RuntimeError("Every context must contain a problem, reference solution, and misconception")
    if any(not r["response_raw"].strip() or not r["draft_next_step"].strip() for r in responses):
        raise RuntimeError("Every response must contain tutor text and a next step")
    context_audit, response_audit, summary = audit(contexts, responses)
    OUT_DIR.mkdir(parents=True, exist_ok=True)
    write_csv(OUT_DIR / "contexts.csv", contexts, CONTEXT_FIELDS)
    write_csv(OUT_DIR / "tutor_response_drafts.csv", responses, RESPONSE_FIELDS)
    write_csv(OUT_DIR / "context_overlap_audit.csv", context_audit, list(context_audit[0]))
    write_csv(OUT_DIR / "response_overlap_audit.csv", response_audit, list(response_audit[0]))
    by_context: dict[str, list[dict[str, Any]]] = defaultdict(list)
    for response in responses:
        by_context[response["context_id"]].append(response)
    with (OUT_DIR / "dataset_draft.jsonl").open("w", encoding="utf-8") as f:
        for context in contexts:
            merged = dict(context)
            merged["responses"] = by_context[context["context_id"]]
            f.write(json.dumps(merged, ensure_ascii=False) + "\n")
    (OUT_DIR / "quality_summary.json").write_text(json.dumps(summary, ensure_ascii=False, indent=2), encoding="utf-8")
    readme = f"""# Full math tutor dataset draft (D1–D4)

This draft contains **{len(contexts)} contexts and {len(responses)} tutor-response drafts**, with {summary['contexts_by_domain'].get('D1', 0)} contexts in each math domain. Each context has one student turn describing a misconception or an attempted answer and one context-specific tutor response draft. The schema follows the project's MRBench-based context and response fields. Revision {VERSION} adds 24 context-response pairs to the previous 160-example set.

## Domain and grade-band allocation

- D1: Number, operations, and quantitative reasoning.
- D2: Algebra, functions, calculus, and linear algebra.
- D3: Geometry, measurement, and trigonometry.
- D4: Statistics, probability, discrete mathematics, and mathematical modeling.
- Every domain includes pre-K, primary, lower-secondary, upper-secondary, and tertiary examples; exact counts are in `quality_summary.json`.

## Files

- `contexts.csv`: one row per context.
- `tutor_response_drafts.csv`: one response draft per context; all eight MRBench annotation fields are blank.
- `dataset_draft.jsonl`: nested form combining each context and its response draft.
- `context_overlap_audit.csv`: exact text and nearest-neighbor checks against MRBench V1 and within this new set.
- `response_overlap_audit.csv`: exact text and nearest-neighbor checks against MRBench V1 tutor responses and within this new set.
- `quality_summary.json`: counts, audit thresholds, status, and release requirements.

## Provenance and review status

These are AI-assisted candidate examples. The tutor responses are written in a human-tutor style but have **not** been authored or approved by a human tutor. All 184 pairs were reviewed for mathematical consistency, a clear misconception, response-to-context alignment, actionable guidance, and topical distinction; 14 inherited draft rows were corrected during this pass. This is an AI review, not teacher sign-off. The team still needs to confirm mathematical correctness, pedagogical and age fit, and novelty. The annotation fields are empty; these drafts are not gold labels. Team attribution and a release license have not yet been decided.

## Duplicate screening

The audit compares all candidate context texts with all 192 MRBench V1 dialogue histories, and all candidate tutor drafts with all available MRBench V1 tutor responses (the source file contains 1,589 response entries). It records exact normalized matches and applies TF-IDF character n-gram screening. Context flags: source raw similarity 0.35, source number-normalized similarity 0.42, within-new-set similarity 0.62. Response flags: source similarity 0.55, within-new-set similarity 0.85. These thresholds are project screening rules, not paper-reported metrics. The current audit found {summary['duplicate_screen']['exact_context_matches_in_mrbench']} exact context matches and {summary['duplicate_screen']['exact_response_matches_in_mrbench']} exact tutor-response matches against MRBench; there are {summary['duplicate_screen']['internal_context_pairs_at_threshold']} internal context pairs and {summary['duplicate_screen']['internal_response_pairs_at_threshold']} internal response pairs at the project's near-duplicate thresholds. {summary['duplicate_screen']['context_review_flags']} context source-neighbor flags received AI review and were judged lexically similar but mathematically distinct (see `context_overlap_audit.csv`); team sign-off is still pending. Exact text checks and lexical scores cannot prove semantic uniqueness on their own.
"""
    (OUT_DIR / "README.md").write_text(readme, encoding="utf-8")
    print(json.dumps({
        "output_dir": str(OUT_DIR), "contexts": len(contexts), "responses": len(responses),
        "by_domain": summary["contexts_by_domain"], "by_grade_band": summary["contexts_by_grade_band"],
        "context_flags": summary["duplicate_screen"]["context_review_flags"],
        "response_flags": summary["duplicate_screen"]["response_review_flags"],
        "exact_context_matches": summary["duplicate_screen"]["exact_context_matches_in_mrbench"],
        "exact_response_matches": summary["duplicate_screen"]["exact_response_matches_in_mrbench"],
        "internal_context_pairs": summary["duplicate_screen"]["internal_context_pairs_at_threshold"],
        "internal_response_pairs": summary["duplicate_screen"]["internal_response_pairs_at_threshold"],
    }, ensure_ascii=False, indent=2))


if __name__ == "__main__":
    main()
